  name         = excluded.name,
  body_parts   = excluded.body_parts,
  equipment    = excluded.equipment,
  modality     = excluded.modality,
  technique    = excluded.technique,
  track_weight = excluded.track_weight;

-- ============================================================ verify
select count(*) as exercises_total,
       count(*) filter (where technique <> '') as with_technique,
       count(*) filter (where technique =  '') as still_blank
  from exercises;

